// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title BondingCurve2 - ANT Token Bonding Curve
 * @notice Implements a Bancor-style bonding curve for ANT token trading
 * @dev Converted from clean_bonding_curve.move (Aptos)
 * 
 * FEATURES:
 * - Buy ANT tokens with CURE (price increases with supply)
 * - Sell ANT tokens for CURE (price decreases with supply)
 * - Automated market maker (always liquid, no order book)
 * - Slippage protection on all trades
 * - View functions for price quotes and statistics
 * 
 * BONDING CURVE MECHANICS:
 * - Uses Bancor formula (simplified for gas efficiency)
 * - 50% reserve ratio for price stability
 * - Starts from zero supply/reserve
 * - Max supply: 10M ANT tokens
 * - Initial price: 0.1 CURE per ANT
 * 
 * SECURITY:
 * - Owner-controlled initialization
 * - Custom errors for gas efficiency
 * - Comprehensive event logging
 * - Slippage protection prevents frontrunning
 * 
 * @author Curable Labs Team
 * @custom:conversion-date November 11, 2025
 */
contract BondingCurve2 {
    
    // State Variables
    address public owner;
    uint256 public currentSupply;        // Current ANT supply
    uint256 public reserveBalance;       // CURE in reserve
    uint256 public reserveRatio;         // Reserve ratio
    uint256 public totalBought;          // Total ANT tokens bought
    uint256 public totalSold;            // Total ANT tokens sold
    bool public curveActive;             // Is curve active for trading
    uint256 public launchTimestamp;      // When curve was launched
    bool public paused;                  // Emergency pause status

    // Constants
    uint256 public constant RESERVE_RATIO = 500000;        // 50% reserve ratio (scaled by 1M)
    uint256 public constant PRECISION = 1000000;           // 1M for calculations
    uint256 public constant MAX_SUPPLY = 10000000000000;   // 10M ANT (scaled by 1M)
    uint256 public constant INITIAL_PRICE = 100000; 
    


    // Mappings
    mapping(address => uint256) public antBalances;    // Track ANT token balances for each user       // 0.1 CURE per ANT (scaled)


    // Events
     event ANTTokenPurchased(
        address indexed buyer,
        uint256 cureAmount,
        uint256 antReceived,
        uint256 newPrice,
        uint256 newSupply
     );

     event ANTTokenSold(
        address indexed seller,
        uint256 antAmount,
        uint256 cureReceived,
        uint256 newPrice,
        uint256 newSupply
     );

     event BondingCurveInitialized(
        address indexed owner,
        uint256 timestamp
     );

     event ANTTransferred(
        address indexed from,
        address indexed to,
        uint256 amount
     );

     event Paused(address indexed by);
     
     event Unpaused(address indexed by);
     
     event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
     );

    
    // Custom Errors
    error InsufficientCURE();
    error InsufficientANT();
    error SlippageExceeded(uint256 expected, uint256 actual);
    error CurveNotInitialized();
    error InvalidAmount();
    error CurveAlreadyInitialized();
    error NotOwner();
    error MaxSupplyExceeded();
    error ContractPaused();
    error InvalidAddress();

    // Modifiers
     modifier onlyOwner()  {
        if(msg.sender != owner) revert NotOwner();
        _;
     }
 
     modifier whenNotPaused() {
        if(paused) revert ContractPaused();
        _;
     }
 
    // Constructor
    constructor() {
        owner = msg.sender;              // Deployer becomes owner
        currentSupply = 0;               // Start with 0 ANT tokens
        reserveBalance = 0;              // Start with 0 CURE in reserve
        reserveRatio = RESERVE_RATIO;    // Set to 50% (500000)
        totalBought = 0;                 // No tokens bought yet
        totalSold = 0;                   // No tokens sold yet
        curveActive = false;             // Not active until initialized
        paused = false;                  // Start unpaused
    }

        // Initialize the bonding curve (owner only, runs once)
    function initializeBondingCurve() external onlyOwner {
        if(curveActive) revert CurveAlreadyInitialized();
    
        curveActive = true;                    // Activate trading
        launchTimestamp = block.timestamp;     // Record launch time
        
        emit BondingCurveInitialized(owner, block.timestamp);
    }


     
      // Buy ANT tokens with CURE (bonding curve pricing)
     // cureAmount = Amount of CURE to spend
    // minAntOut = Minimum ANT tokens expected (slippage protection)
    function buyANTTokens(uint256 cureAmount, uint256 minAntOut) external payable whenNotPaused {
        if(!curveActive) revert CurveNotInitialized();
        if(cureAmount == 0) revert InvalidAmount();
        
        // Calculate how many ANT tokens to give using bonding curve formula
        uint256 antToMint = calculatePurchaseAmount(currentSupply, reserveBalance, cureAmount);
        
        // Check slippage protection
        if(antToMint < minAntOut) revert SlippageExceeded(minAntOut, antToMint);
        
        // Check max supply not exceeded
        uint256 newSupply = currentSupply + antToMint;
        if(newSupply > MAX_SUPPLY) revert MaxSupplyExceeded();
        
        // Update state
        currentSupply = newSupply;
        reserveBalance = reserveBalance + cureAmount;
        totalBought = totalBought + antToMint;
        antBalances[msg.sender] = antBalances[msg.sender] + antToMint;
        
        // Calculate new price
        uint256 newPrice = calculateCurrentPrice(currentSupply, reserveBalance);
        
        emit ANTTokenPurchased(msg.sender, cureAmount, antToMint, newPrice, newSupply);
    }

        // Sell ANT tokens for CURE (bonding curve pricing)
    // antAmount = Amount of ANT tokens to sell
    // minCureOut = Minimum CURE expected (slippage protection)
    function sellANTTokens(uint256 antAmount, uint256 minCureOut) external whenNotPaused {
        if(!curveActive) revert CurveNotInitialized();
        if(antAmount == 0) revert InvalidAmount();
        if(antBalances[msg.sender] < antAmount) revert InsufficientANT();
        
        // Calculate how much CURE to return using bonding curve formula
        uint256 cureToReturn = calculateSaleAmount(currentSupply, reserveBalance, antAmount);
        
        // Check slippage protection
        if(cureToReturn < minCureOut) revert SlippageExceeded(minCureOut, cureToReturn);
        
        // Check reserve has enough CURE
        if(cureToReturn > reserveBalance) revert InsufficientCURE();
        
        // Update state
        currentSupply = currentSupply - antAmount;
        reserveBalance = reserveBalance - cureToReturn;
        totalSold = totalSold + antAmount;
        antBalances[msg.sender] = antBalances[msg.sender] - antAmount;
        
        // Calculate new price
        uint256 newPrice = calculateCurrentPrice(currentSupply, reserveBalance);
        
        // TODO: Transfer CURE to seller (needs CURE token integration)
        
        emit ANTTokenSold(msg.sender, antAmount, cureToReturn, newPrice, currentSupply);
    }




    // ========== HELPER FUNCTIONS (Internal Math) ==========
    
    // Calculate tokens to mint for purchase (Bancor formula)
    // supply = Current ANT supply
    // reserve = Current CURE in reserve
    // cureDeposit = Amount of CURE being deposited
    function calculatePurchaseAmount(
        uint256 supply,
        uint256 reserve,
        uint256 cureDeposit
    ) internal pure returns (uint256) {
        // If first purchase, use initial price
        if (supply == 0) {
            return (cureDeposit * PRECISION) / INITIAL_PRICE;
        }
        
        // Bancor formula (simplified for gas efficiency):
        // tokens_out ≈ (cure_in * supply) / (reserve + cure_in/2)
        uint256 numerator = cureDeposit * supply;
        uint256 denominator = reserve + cureDeposit / 2;
        
        if (denominator == 0) {
            return 0;
        }
        
        return numerator / denominator;
    }
    
    // Calculate CURE to return for sale (reverse Bancor)
    // supply = Current ANT supply
    // reserve = Current CURE in reserve
    // antToBurn = Amount of ANT being sold
    function calculateSaleAmount(
        uint256 supply,
        uint256 reserve,
        uint256 antToBurn
    ) internal pure returns (uint256) {
        // Safety checks
        if (supply == 0 || supply <= antToBurn) {
            return 0;
        }
        
        // Reverse Bancor formula (simplified):
        // cure_out ≈ (tokens_in * reserve) / (supply - tokens_in/2)
        uint256 numerator = antToBurn * reserve;
        uint256 denominator = supply - antToBurn / 2;
        
        if (denominator == 0) {
            return 0;
        }
        
        return numerator / denominator;
    }
    
    // Calculate current token price
    // supply = Current ANT supply
    // reserve = Current CURE in reserve
    function calculateCurrentPrice(uint256 supply, uint256 reserve) internal pure returns (uint256) {
        // If no supply yet, return initial price
        if (supply == 0) {
            return INITIAL_PRICE;
        }
        
        // Price = reserve / supply (in CURE per ANT)
        return (reserve * PRECISION) / supply;
    }    


    // ========== VIEW FUNCTIONS ==========
    
    // Get quote for buying ANT tokens
    // cureAmount = Amount of CURE user wants to spend
    // Returns: Amount of ANT tokens they would receive
    function getBuyQuote(uint256 cureAmount) external view returns (uint256) {
        return calculatePurchaseAmount(currentSupply, reserveBalance, cureAmount);
    }
    
    // Get quote for selling ANT tokens
    // antAmount = Amount of ANT tokens user wants to sell
    // Returns: Amount of CURE they would receive
    function getSellQuote(uint256 antAmount) external view returns (uint256) {
        return calculateSaleAmount(currentSupply, reserveBalance, antAmount);
    }
    
    // Get current ANT token price in CURE
    // Returns: Current price (CURE per ANT, scaled by PRECISION)
    function getCurrentPrice() external view returns (uint256) {
        return calculateCurrentPrice(currentSupply, reserveBalance);
    }
    
    // Get comprehensive bonding curve statistics
    // Returns: All key curve metrics in one call
    function getCurveStats() external view returns (
        uint256 supply,
        uint256 reserve,
        uint256 price,
        uint256 bought,
        uint256 sold,
        bool active,
        uint256 launched
    ) {
        return (
            currentSupply,
            reserveBalance,
            calculateCurrentPrice(currentSupply, reserveBalance),
            totalBought,
            totalSold,
            curveActive,
            launchTimestamp
        );
    }
    
    // Get ANT token balance for an address
    // account = Address to check balance for
    // Returns: ANT token balance
    function getANTBalance(address account) external view returns (uint256) {
        return antBalances[account];
    }

    // ========== ADMIN & TRANSFER FUNCTIONS ==========
    
    // Transfer ANT tokens to another address
    // to = Recipient address
    // amount = Amount of ANT tokens to transfer
    function transferANT(address to, uint256 amount) external {
        if(to == address(0)) revert InvalidAddress();
        if(amount == 0) revert InvalidAmount();
        if(antBalances[msg.sender] < amount) revert InsufficientANT();
        
        antBalances[msg.sender] -= amount;
        antBalances[to] += amount;
        
        emit ANTTransferred(msg.sender, to, amount);
    }
    
    // Emergency pause trading (owner only)
    function pause() external onlyOwner {
        paused = true;
        emit Paused(msg.sender);
    }
    
    // Resume trading after pause (owner only)
    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused(msg.sender);
    }
    
    // Transfer ownership to new address (owner only)
    // newOwner = Address of new owner
    function transferOwnership(address newOwner) external onlyOwner {
        if(newOwner == address(0)) revert InvalidAddress();
        
        address oldOwner = owner;
        owner = newOwner;
        
        emit OwnershipTransferred(oldOwner, newOwner);
    }
}

contracts/CleanDeployReady.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
* @title CleanDeployReady
* @dev Tri-lane tokenomics system for Drug Discovery
* @notice lane 1: Lab Credits (IP proof) / Lane 2: CURE Tokens (Funding) / Lane 3: Sub-DAOs (Marketplaces)
* @author Curable Labs Team
*/


contract CleanDeployReady {
    // State Variables
    address public admin;
    uint64 public labCreditsIssued;
    uint256 public cureTotalSupply;
    uint64 public subdaoCount; 

    // Structs

/// @dev Lab Credit - Non-transferable IP Proof 
    struct LabCredit {
        uint64 creditId;
        address inventor;
        string ipTitle;
        uint64 timestamp;
        bool exists;
    }

/// @dev CURE Token Holder Information
    struct CUREHolder {
        uint256 balance;
        uint256 staked;
        uint8 phase; // 1 = fixed pricing, 2 = dynamic pricing
    }

/// @dev Sub-DAO token for disease-specific research 
    struct SubDAOToken {
        uint64 daoId;
        uint256 tokenSupply;
        bool bondingActive;
     }

  // Mapping

   mapping(address => LabCredit) public labCredits;
   mapping(address => CUREHolder) public cureHolders;
   mapping(address => SubDAOToken) public subDAOTokens;
   mapping(uint64 => address) public subDAOById;

 // Events 
  
    event LabCreditIssued(uint64 indexed creditId, address indexed inventor, string ipTitle, uint64 timestamp);
    event CURETokensAcquired(address indexed buyer, uint256 amount, uint256 newBalance);
    event CUREStaked(address indexed staker, uint256 amount, uint256 totalStaked);
    event SubDAOCreated(uint64 indexed daoId, address indexed creator, uint256 initialSupply);
    event Phase2Activated(address indexed holder, uint256 timestamp);
    event BondingCurveToggled(uint64 indexed daoId, bool active);

 // Errors

    error NotAdmin();
    error InsufficientBalance();
    error InvalidAmount();
    error LabCreditAlreadyExists();
    error LabCreditNotFound();
    error CUREHolderNotFound();
    error SubDAONotFound();

 // modifiers

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAdmin();
        _;
    }

 // constructor

    constructor() {
        admin = msg.sender;
        labCreditsIssued = 0;
        cureTotalSupply = 0;
        subdaoCount = 0;
    }

        
// ========================================
// Lane 1: Lab Credit Functions
// ========================================
    
        
       
    /**
     * @notice Issue a non-transferable Lab Credit for intellectual property
     * @param ipTitle Title/description of the intellectual property
     */
    function issueLabCredit(string memory ipTitle) external {
        if(labCredits[msg.sender].exists) revert LabCreditAlreadyExists();
        if(bytes(ipTitle).length == 0) revert InvalidAmount();
        
        labCreditsIssued++;
        
        labCredits[msg.sender] = LabCredit({
            creditId: labCreditsIssued,
            inventor: msg.sender,
            ipTitle: ipTitle,
            timestamp: uint64(block.timestamp),
            exists: true
        });
        
        emit LabCreditIssued(labCreditsIssued, msg.sender, ipTitle, uint64(block.timestamp));
    }
    
    
// ========================================
// Lane 2: CURE Token    
// ========================================

        
    /**
     * @notice Acquire CURE tokens for community participation
     * @param amount Amount of CURE tokens to acquire
     */
    function acquireCURETokens(uint256 amount) external payable {
        if(amount == 0) revert InvalidAmount();
        
        cureTotalSupply += amount;
        
        CUREHolder storage holder = cureHolders[msg.sender];
        holder.balance += amount;
        
        if(holder.phase == 0) {
            holder.phase = 1; // Initialize to Phase 1
        }
        
        emit CURETokensAcquired(msg.sender, amount, holder.balance);
    }



    /**
     * @notice Stake CURE tokens on research proposals
     * @param stakeAmount Amount of CURE tokens to stake
     */
    function stakeCUREOnResearch(uint256 stakeAmount) external {
        if(stakeAmount == 0) revert InvalidAmount();
        
        CUREHolder storage holder = cureHolders[msg.sender];
        if(holder.balance < stakeAmount) revert InsufficientBalance();
        
        holder.balance -= stakeAmount;
        holder.staked += stakeAmount;
        
        emit CUREStaked(msg.sender, stakeAmount, holder.staked);
    }
    
    // ========================================
    // Lane 3: Sub-DAO Functions
    // ========================================
    
    /**
     * @notice Create a disease-specific Sub-DAO with its own token
     * @param initialSupply Initial token supply for the Sub-DAO
     */
    function createSubDAO(uint256 initialSupply) external {
        if(initialSupply == 0) revert InvalidAmount();
        
        subdaoCount++;
        
        subDAOTokens[msg.sender] = SubDAOToken({
            daoId: subdaoCount,
            tokenSupply: initialSupply,
            bondingActive: true
        });
        
        subDAOById[subdaoCount] = msg.sender;
        
        emit SubDAOCreated(subdaoCount, msg.sender, initialSupply);
    }

        
    // ========================================
    // Admin Functions
    // ========================================
    
    /**
     * @notice Activate Phase 2 (dynamic pricing) for a CURE holder
     * @param holder Address of the CURE token holder
     */
    function activatePhase2(address holder) external onlyAdmin {
        CUREHolder storage cureHolder = cureHolders[holder];
        if(cureHolder.phase == 0) revert CUREHolderNotFound();
        
        cureHolder.phase = 2;
        emit Phase2Activated(holder, block.timestamp);
    } 


        
    /**
     * @notice Toggle bonding curve status for a Sub-DAO
     * @param daoCreator Address of the Sub-DAO creator
     * @param active New bonding curve status
     */
    function toggleBondingCurve(address daoCreator, bool active) external onlyAdmin {
        SubDAOToken storage subdao = subDAOTokens[daoCreator];
        if(subdao.daoId == 0) revert SubDAONotFound();
        
        subdao.bondingActive = active;
        emit BondingCurveToggled(subdao.daoId, active);
    }

        
    // ========================================
    // View Functions
    // ========================================
    
    /**
     * @notice Get system-wide statistics
     * @return Number of lab credits, total CURE supply, and number of Sub-DAOs
     */
    function getSystemStats() external view returns (uint64, uint256, uint64) {
        return (labCreditsIssued, cureTotalSupply, subdaoCount);
    }

        
    /**
     * @notice Get Lab Credit details for an inventor
     * @param inventor Address of the inventor
     * @return Lab Credit information
     */
    function getLabCredit(address inventor) external view returns (LabCredit memory) {
        if(!labCredits[inventor].exists) revert LabCreditNotFound();
        return labCredits[inventor];
    }

        
    /**
     * @notice Get CURE token balance and staking info for a holder
     * @param holder Address of the CURE holder
     * @return Balance, staked amount, and phase
     */
    function getCUREBalance(address holder) external view returns (uint256, uint256, uint8) {
        CUREHolder memory holderInfo = cureHolders[holder];
        if(holderInfo.phase == 0) revert CUREHolderNotFound();
        return (holderInfo.balance, holderInfo.staked, holderInfo.phase);
    }

    
    /**
     * @notice Get Sub-DAO information
     * @param creator Address of the Sub-DAO creator
     * @return Sub-DAO details
     */
    function getSubDAOInfo(address creator) external view returns (SubDAOToken memory) {
        if(subDAOTokens[creator].daoId == 0) revert SubDAONotFound();
        return subDAOTokens[creator];
    }
}

contracts/CUREIntegration2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title CUREIntegration - CURE Token Integration for ANT Scoring
 * @notice Connects CURE token economy with research scoring system
 * @dev Converted from clean_cure_integration.move (Aptos)
 
 * 
 * @author Curable Labs Team
 * @custom:conversion-date November 12, 2025
 */
contract CUREIntegration {
    
    // Constants
    uint256 public constant MIN_SCORER_STAKE = 1000 * 10**18;     // 1000 CURE minimum to be scorer
    uint256 public constant PROPOSAL_FEE = 10 * 10**18;           // 10 CURE to submit proposal
    uint256 public constant ACCURACY_BONUS_RATE = 50 * 10**18;   // 50 CURE bonus for accurate scoring
    uint256 public constant VOTING_PERIOD = 7 days;               // 7 days voting period
    

    

    // State Variable
    address public owner;                // Contract owner
    uint256 public totalCureStaked;      // Total CURE staked by all scorers
    uint256 public totalScorers;         // Total number of scorers
    uint256 public proposalCounter;      // Counter for proposal IDs
    uint256 public communityTreasury;    // CURE collected from proposal fees
    uint256 public rewardPool;           // CURE allocated for rewards
    bool public paused;                  // Emergency pause state




    // Structs
    struct ScorerStake {
        uint256 stakedAmount;
        uint256 votingPower;
        uint256 rewardsEarned;
        uint256 accuracyScore;
        uint256 lastRewardClaim;
    }



    struct GovernanceProposal {
        uint256 proposalId;
        address proposer;
        string title;
        string description;
        uint8 newScientificMeritWeight;
        uint8 newFeasibilityWeight;
        uint8 newCommunityWeight;
        uint8 newResourceWeight;
        uint8 newOpenScienceWeight;
        uint256 cureVotesFor;
        uint256 cureVotesAgainst;
        uint256 votingEnds;
        uint8 status;
    }

    


    // Mappings
    mapping(address => ScorerStake) public scorerStakes;
    mapping(uint256 => GovernanceProposal) public proposals;
    mapping(uint256 => mapping(address => bool)) public hasVoted;


    // Events
    event ScorerStaked(
        address indexed scorer,
        uint256 amount,
        uint256 newVotingPower
    );

    event GovernanceProposalCreated(
        uint256 indexed proposalId,
        address indexed proposer,
        string title
    );

    event CURERewardPaid(
        address indexed scorer,
        uint256 amount,
        string reason
    );

    event ProposalVoted(
        uint256 indexed proposalId,
        address indexed voter,
        bool voteFor,
        uint256 votingPower
    );

    event ScorerUnstaked(
        address indexed scorer,
        uint256 amount
    );

    event ProposalFinalized(
        uint256 indexed proposalId,
        uint8 finalStatus
    );

    event RewardsClaimed(
        address indexed scorer,
        uint256 amount
    );

    event AccuracyUpdated(
        address indexed scorer,
        uint256 oldAccuracy,
        uint256 newAccuracy,
        uint256 newVotingPower
    );

    event StakeIncreased(
        address indexed scorer,
        uint256 additionalAmount,
        uint256 newVotingPower
    );

    event ProposalCancelled(
        uint256 indexed proposalId,
        address indexed proposer
    );

    event Paused(address indexed by);
    event Unpaused(address indexed by);
    
    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );


    // Custom Errors
    error InsufficientStake();
    error NotAuthorizedScorer();
    error ProposalNotFound();
    error InsufficientCURE();
    error InvalidWeights();
    error ProposalNotActive();
    error VotingEnded();
    error AlreadyVoted();
    error NotOwner();
    error NoRewardsAvailable();
    error InvalidAccuracy();
    error NotProposer();
    error ProposalAlreadyFinalized();
    error VotingStillActive();
    error ContractPaused();
    error InvalidAddress();



    // Modifiers
    modifier onlyOwner() {
        if(msg.sender != owner) revert NotOwner();
        _;
    }

    modifier onlyScorer() {
        if(scorerStakes[msg.sender].stakedAmount == 0) revert NotAuthorizedScorer();
        _;
    }

    modifier whenNotPaused() {
        if(paused) revert ContractPaused();
        _;
    }



    // Constructor
    constructor() {
        owner = msg.sender;
        totalCureStaked = 0;
        totalScorers = 0;
        proposalCounter = 0;
        communityTreasury = 0;
        rewardPool = 0;
        paused = false;
    }




    // ========== CORE FUNCTIONS ==========
    
    // Stake CURE tokens to become authorized scorer
    // stakeAmount = Amount of CURE to stake
    function stakeToBeScorer(uint256 stakeAmount) external whenNotPaused {
        if(stakeAmount < MIN_SCORER_STAKE) revert InsufficientStake();
        
        // TODO: Transfer CURE from scorer (needs CURE token integration)
        
        uint256 votingPower = calculateVotingPower(stakeAmount);
        
        scorerStakes[msg.sender] = ScorerStake({
            stakedAmount: stakeAmount,
            votingPower: votingPower,
            rewardsEarned: 0,
            accuracyScore: 100,
            lastRewardClaim: block.timestamp
        });
        
        totalCureStaked += stakeAmount;
        totalScorers += 1;
        
        emit ScorerStaked(msg.sender, stakeAmount, votingPower);
    }

        

    // Pay proposal fee (for researchers submitting proposals)
    // Returns: Amount paid
    function payProposalFee() external returns (uint256) {
        // TODO: Transfer CURE from researcher (needs CURE token integration)
        communityTreasury += PROPOSAL_FEE;
        return PROPOSAL_FEE;
    }

    


    // Create governance proposal to change scoring weights
    function createGovernanceProposal(
        string memory title,
        string memory description,
        uint8 newScientificMeritWeight,
        uint8 newFeasibilityWeight,
        uint8 newCommunityWeight,
        uint8 newResourceWeight,
        uint8 newOpenScienceWeight
    ) external onlyScorer {
        // Verify weights sum to 100
        uint8 totalWeight = newScientificMeritWeight + newFeasibilityWeight + 
                           newCommunityWeight + newResourceWeight + newOpenScienceWeight;
        if(totalWeight != 100) revert InvalidWeights();
        
        proposalCounter += 1;
        uint256 proposalId = proposalCounter;
        
        proposals[proposalId] = GovernanceProposal({
            proposalId: proposalId,
            proposer: msg.sender,
            title: title,
            description: description,
            newScientificMeritWeight: newScientificMeritWeight,
            newFeasibilityWeight: newFeasibilityWeight,
            newCommunityWeight: newCommunityWeight,
            newResourceWeight: newResourceWeight,
            newOpenScienceWeight: newOpenScienceWeight,
            cureVotesFor: 0,
            cureVotesAgainst: 0,
            votingEnds: block.timestamp + VOTING_PERIOD,
            status: 0
        });
        
        emit GovernanceProposalCreated(proposalId, msg.sender, title);
    }

        

    // Vote on governance proposal with CURE voting power
    function voteOnProposal(uint256 proposalId, bool voteFor) external onlyScorer whenNotPaused {
        if(proposals[proposalId].proposalId == 0) revert ProposalNotFound();
        if(proposals[proposalId].status != 0) revert ProposalNotActive();
        if(block.timestamp >= proposals[proposalId].votingEnds) revert VotingEnded();
        if(hasVoted[proposalId][msg.sender]) revert AlreadyVoted();
        
        uint256 votingPower = scorerStakes[msg.sender].votingPower;
        
        if(voteFor) {
            proposals[proposalId].cureVotesFor += votingPower;
        } else {
            proposals[proposalId].cureVotesAgainst += votingPower;
        }
        
        hasVoted[proposalId][msg.sender] = true;
        
        emit ProposalVoted(proposalId, msg.sender, voteFor, votingPower);
    }



    // Reward accurate scorer with CURE tokens (owner only)
    function rewardAccurateScorer(address scorer, uint256 bonusAmount) external onlyOwner {
        if(scorerStakes[scorer].stakedAmount == 0) revert NotAuthorizedScorer();
        
        scorerStakes[scorer].rewardsEarned += bonusAmount;
        rewardPool += bonusAmount;
        
        emit CURERewardPaid(scorer, bonusAmount, "Accurate scoring bonus");
    }


    // ========== PRODUCTION FEATURES ==========

    // FEATURE 1: Unstake CURE tokens and stop being scorer
    function unstakeScorer() external onlyScorer {
        uint256 stakedAmount = scorerStakes[msg.sender].stakedAmount;
        
        // TODO: Transfer CURE back to scorer (needs CURE token integration)
        
        delete scorerStakes[msg.sender];
        totalCureStaked -= stakedAmount;
        totalScorers -= 1;
        
        emit ScorerUnstaked(msg.sender, stakedAmount);
    }


    // FEATURE 2: Finalize/Execute proposal after voting period ends
    function finalizeProposal(uint256 proposalId) external {
        GovernanceProposal storage proposal = proposals[proposalId];
        
        if(proposal.proposalId == 0) revert ProposalNotFound();
        if(proposal.status != 0) revert ProposalAlreadyFinalized();
        if(block.timestamp < proposal.votingEnds) revert VotingStillActive();
        
        // Determine result based on votes
        if(proposal.cureVotesFor > proposal.cureVotesAgainst) {
            proposal.status = 1; // Passed
            // TODO: Actually apply the new weights to ANTScoring contract
        } else {
            proposal.status = 2; // Rejected
        }
        
        emit ProposalFinalized(proposalId, proposal.status);
    }


    // FEATURE 3: Claim accumulated rewards
    function claimRewards() external onlyScorer {
        uint256 rewards = scorerStakes[msg.sender].rewardsEarned;
        if(rewards == 0) revert NoRewardsAvailable();
        
        scorerStakes[msg.sender].rewardsEarned = 0;
        scorerStakes[msg.sender].lastRewardClaim = block.timestamp;
        
        // TODO: Transfer CURE rewards to scorer (needs CURE token integration)
        
        emit RewardsClaimed(msg.sender, rewards);
    }


    // FEATURE 4: Update scorer's accuracy score (owner only)
    function updateScorerAccuracy(address scorer, uint256 newAccuracy) external onlyOwner {
        if(newAccuracy > 100) revert InvalidAccuracy();
        if(scorerStakes[scorer].stakedAmount == 0) revert NotAuthorizedScorer();
        
        uint256 oldAccuracy = scorerStakes[scorer].accuracyScore;
        scorerStakes[scorer].accuracyScore = newAccuracy;
        
        // Recalculate voting power based on new accuracy
        uint256 newPower = calculateVotingPower(scorerStakes[scorer].stakedAmount);
        scorerStakes[scorer].votingPower = newPower;
        
        emit AccuracyUpdated(scorer, oldAccuracy, newAccuracy, newPower);
    }


    // FEATURE 5: Increase stake amount (add more CURE)
    function increaseStake(uint256 additionalAmount) external onlyScorer whenNotPaused {
        if(additionalAmount == 0) revert InsufficientStake();
        
        // TODO: Transfer additional CURE from scorer (needs CURE token integration)
        
        scorerStakes[msg.sender].stakedAmount += additionalAmount;
        uint256 newPower = calculateVotingPower(scorerStakes[msg.sender].stakedAmount);
        scorerStakes[msg.sender].votingPower = newPower;
        
        totalCureStaked += additionalAmount;
        
        emit StakeIncreased(msg.sender, additionalAmount, newPower);
    }


    // FEATURE 6: Cancel your own proposal (before it's finalized)
    function cancelProposal(uint256 proposalId) external {
        GovernanceProposal storage proposal = proposals[proposalId];
        
        if(proposal.proposalId == 0) revert ProposalNotFound();
        if(proposal.proposer != msg.sender) revert NotProposer();
        if(proposal.status != 0) revert ProposalAlreadyFinalized();
        
        proposal.status = 3; // Cancelled
        
        emit ProposalCancelled(proposalId, msg.sender);
    }


    // FEATURE 7: Emergency pause (owner only)
    function pause() external onlyOwner {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused(msg.sender);
    }


    // FEATURE 8: Transfer contract ownership
    function transferOwnership(address newOwner) external onlyOwner {
        if(newOwner == address(0)) revert InvalidAddress();
        
        address oldOwner = owner;
        owner = newOwner;
        
        emit OwnershipTransferred(oldOwner, newOwner);
    }


    // ========== HELPER FUNCTIONS ==========
    
    // Calculate voting power based on stake amount
    function calculateVotingPower(uint256 stakeAmount) internal pure returns (uint256) {
        return stakeAmount;
    }


    // ========== VIEW FUNCTIONS ==========
    
    // Get scorer stake information
    function getScorerStake(address scorer) external view returns (ScorerStake memory) {
        if(scorerStakes[scorer].stakedAmount == 0) revert NotAuthorizedScorer();
        return scorerStakes[scorer];
    }

    // Get governance proposal details
    function getGovernanceProposal(uint256 proposalId) external view returns (GovernanceProposal memory) {
        if(proposals[proposalId].proposalId == 0) revert ProposalNotFound();
        return proposals[proposalId];
    }

    // Get integration statistics
    function getIntegrationStats() external view returns (
        uint256 _totalCureStaked,
        uint256 _totalScorers,
        uint256 _communityTreasury,
        uint256 _rewardPool
    ) {
        return (totalCureStaked, totalScorers, communityTreasury, rewardPool);
    }

    
}

